// ═══════════════════════════════════════════════════════════════════════
//  POS Adorno · manual.js — Manual de uso (overlay 📖, autoinyectable)
//  🚨 REGLA: cada vez que se agrega o cambia una función del módulo,
//  actualizar la sección correspondiente acá (y bump del ?v= en index.html).
// ═══════════════════════════════════════════════════════════════════════

function _mEsc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function _manualSecciones() {
  return [
    { icon: '🧭', titulo: 'La barra de arriba', desc: 'Es igual en todos los módulos: mismo lugar para cada cosa y el color de la moneda del módulo (el mismo del Hub).',
      pasos: ['A la izquierda, la moneda y el nombre del módulo. En la computadora, tocando el nombre (POS ▾) se abre la lista para pasar a otro módulo; al final de esa lista está «Volver al Hub».', 'Al lado van los apartados (Vender, Comprobantes, Remitos, Pedidos, Etiquetas, Vales, Caja, Ajustes): son íconos; al pasar el mouse aparece el nombre, y el apartado en el que estás queda marcado en blanco con su nombre.', 'A la derecha: el tamaño de letra (A− / A+), ↺ Volver a lo normal y Salir.', 'En el celular: los apartados están adentro del botón ☰; a la vista quedan 🏠 Hub (volver al Hub) y Salir.', '¿Dudas? Preguntale a Clodi (el botón de abajo a la derecha): sabe todo lo que dice este manual.'] },
    { icon: '↩', titulo: 'Nota de crédito sin factura asociada', desc: 'La nota de crédito se puede hacer con o sin factura asociada. Asociarla es lo mejor cuando existe (devolución de una venta del POS); sin asociar sirve para un descuento bancario, un ajuste o la devolución de una factura que no está en el POS (por ejemplo una del Dragonfish).',
      pasos: ['Con factura: pastilla Nota de crédito, buscás la factura por número o cliente y entran sus renglones; la nota sale con la misma letra y el mismo cliente, y no puede devolver más de lo que queda.', 'Sin factura: pastilla Nota de crédito y no elegís ninguna factura. Cargás el cliente como en una venta (define si es B o A) y los renglones: productos del buscador (si vuelve mercadería, sube el stock) o «＋ Agregar un concepto sin mercadería» para un descuento o ajuste: escribís el concepto y el importe, y no mueve stock.', 'Después elegís cómo se le devuelve la plata (efectivo, vale de cambio, etc.) y emitís. Igual que siempre, la nota de crédito necesita la autorización de la encargada o la cajera.', 'Sin factura asociada no hay devolución automática por el Point: la devolución a la tarjeta se hace desde la terminal.', 'A ARCA la nota sin factura se informa con el período (del día 1 del mes a la fecha) en lugar del comprobante asociado.'] },
    { icon: '🔎', titulo: 'Cobros por Mercado Pago: se verifican antes de emitir', desc: 'Cuando el cliente paga por transferencia a la cuenta de Mercado Pago, con el Point o el QR «No integrado», o con un link de pago, el POS busca ese cobro en la cuenta antes de emitir la factura. Ya no hace falta entrar a Tesorería a mirar las transferencias: la consulta es la misma y la hace el POS.',
      pasos: ['Elegí el medio (Transferencia, Point o QR en «No integrado», Link de pago) y poné el importe exacto que pagó el cliente.', 'Cuando el cliente avisa que ya pagó, tocá «Verificar» (o directamente Emitir: verifica primero). El POS consulta la cuenta cada pocos segundos, hasta dos minutos.', 'Cuando el cobro aparece queda el tilde verde «está en Mercado Pago» con el día y la hora, el código queda anotado como referencia y, si el ticket está pagado completo, la factura se emite sola.', 'Si hay más de un cobro por el mismo importe, muestra la lista para elegir cuál es (mirá la hora y el código del comprobante del cliente).', 'Cada cobro sirve para un solo comprobante: una vez usado no vuelve a aparecer. La transferencia queda además marcada como reclamada en Tesorería.', 'Si no aparece (demora de Mercado Pago, o el cliente transfirió a otra cuenta): «Sin verificar» deja emitir con la autorización de la encargada o la cajera, y queda registrado.', 'Qué busca: transferencia = lo que entró a la cuenta en las últimas 24 horas; Point y QR no integrados = cobros de este local de las últimas 3 horas; link = pagos sin local de las últimas 3 horas. Siempre por importe exacto.', 'En Oficina funciona igual, pero como la venta online se cobra primero y se factura después, busca el cobro hasta 15 días para atrás: al tocar Emitir lo encuentra solo y emite. Si el cobro entró por otra cuenta (el banco, u otra cuenta de Mercado Pago) no lo va a ver: ahí va «Sin verificar».', 'No aplica en notas de crédito, remitos ni presupuestos. El Point integrado no lo necesita: ya confirma solo.'] },
    { icon: '🔗', titulo: 'Link de pago de Mercado Pago desde el POS', desc: 'El link de pago se arma desde el mismo ticket, sin entrar a Mercado Pago: el POS lo genera por el importe, lo manda por WhatsApp y después verifica solo si el cliente pagó.',
      pasos: ['Cargá los artículos y el cliente. En la forma de pago elegí «Link de pago» y dejá el importe (viene el total).', 'Tocá «Generar link». Se abre la ventana con el link: poné el WhatsApp del cliente (viene cargado si lo tiene en la ficha) y «Enviar por WhatsApp» abre el chat con el mensaje y el link listos. También se puede copiar.', 'El renglón queda con la marca «link generado». El link vence a las 48 horas y sirve para un solo pago por ese importe.', 'Cuando el cliente avisa que pagó, tocá «¿Pagó?» (o Emitir). El POS le pregunta a Mercado Pago por ese link en particular, no por importe: no se confunde con otro cobro. Si está pago, la factura se emite sola.', 'Si todavía no pagó, avisa y se puede volver a consultar las veces que haga falta. «Link» reabre la ventana del link; la cruz lo descarta (por ejemplo para cambiar el importe).', 'Si el cliente pagó con un link armado a mano en Mercado Pago: «Verificar» lo busca por importe, como antes.', 'Ojo: el link cobra de verdad aunque el POS esté en modo prueba, igual que el Point.'] },
    { icon: '⏳', titulo: 'CAI de los remitos: vencimiento y aviso', desc: 'El CAI es el código que ARCA autoriza para imprimir los remitos R de cada punto de venta (los de talonario de imprenta). Dura un año y hay que pedir uno nuevo antes de que venza. En Ajustes → «CAI de los remitos» está la lista con el punto de venta, el número de CAI, la numeración autorizada, el vencimiento y cuántos días faltan.',
      pasos: ['El sistema revisa los vencimientos todos los días a las 9: cuando a un CAI le faltan 14 días o menos (o ya venció) les llega un aviso al celu a los admin, y se repite cada semana hasta que se cargue el nuevo.', 'Para renovarlo: ARCA con clave fiscal → Autorización de Impresión de Comprobantes → Claudia Adorno S.R.L. → Contribuyente → Solicitud de C.A.I. (lo hace la imprenta o el contador).', 'Cuando está el CAI nuevo, un admin entra a Ajustes → «CAI de los remitos» → «Cargar el nuevo» y completa el número, el vencimiento y la numeración. Ahí se apaga el aviso.', 'Si un punto de venta ya no se usa, se destilda «Avisar cuando esté por vencer» y no molesta más.', 'El POS no entra solo a ARCA (necesita la clave fiscal): los datos son los que se cargan acá. El remito que emite el POS es un comprobante interno X y no usa CAI.'] },
    { icon: '🏢', titulo: 'Facturar con la sucursal Oficina desde un local', desc: 'Hoy esto está habilitado solo para Unicenter. Alcorta no puede facturar con la sucursal Oficina (no le aparece Oficina en el selector de local), porque mientras factura por debajo del mínimo del alquiler no tiene sentido desviar facturas a Oficina; cuando haga falta, un admin lo vuelve a habilitar. En un local habilitado, las chicas pueden facturar con la sucursal Oficina eligiéndola arriba, en el selector de local. Con Oficina elegida, el local solo puede facturar: tiene Vender (factura y nota de crédito), Comprobantes y Vales. No puede hacer remitos, presupuestos, comprobantes manuales ni movimientos de stock de Oficina, y no ve Pedidos, Etiquetas ni la Caja de Oficina; para todo eso vuelve a su local en el selector. Facturando con Oficina (desde la propia Oficina o desde Unicenter eligiendo Oficina arriba) aparece además la forma de pago «Cuenta corriente», que no existe facturando con el local: es solo para Oficina. Esa factura sale con el punto de venta y el stock de Oficina, pero la venta se le computa al local que la hizo.',
      pasos: ['El POS anota solo de qué local es la venta: mira el usuario que está abierto (el genérico de Alcorta = Alcorta). No hay que cargar nada.', 'En Comprobantes de Oficina esas facturas llevan la marca violeta «venta de Alcorta» (o del local que sea).', 'Un local que entra a la sucursal Oficina ve en Comprobantes solo lo que emitió ese local (y los traslados que Oficina le manda): los comprobantes propios de Oficina y los del otro local no le aparecen.', 'En la planilla de ventas van a la columna «Fc Oficina» del local, no a las ventas de Oficina. Una nota de crédito sobre esa factura sigue al mismo local.', 'Si la factura la hace alguien de Oficina o un admin con la sucursal Oficina, es venta de Oficina.'] },
    { icon: '📊', titulo: 'Cruce del POS con la planilla de ventas', desc: 'El POS arma solo lo que va a la planilla de ventas de cada local (Alcorta, Unicenter, Oficina), con las mismas columnas que la planilla. En Ajustes → «Planilla de ventas · cruce con el POS» (solo admin) se ve el cálculo de cualquier día y, debajo, lo que hoy tiene cargado la planilla para comparar.',
      pasos: ['Facturas A y B (menos las notas de crédito): se reparten por forma de pago. Efectivo y dólares → Efectivo; Point, QR y link → QR / MP; transferencia → Transferencia; vale o gift card → Vales; cuenta corriente → Cta. cte.', 'Comprobantes X (factura manual) → columna Online, y su parte en efectivo es el «efectivo negro» de la planilla.', 'Facturas que un local hizo con la sucursal Oficina → columna «Fc Oficina» de ese local. No cuentan como venta de Oficina.', 'Remitos y presupuestos no son venta: no entran. Los comprobantes anulados y los de prueba tampoco.', 'Mientras el POS esté en modo prueba, o el cruce esté apagado, NO se carga nada en la planilla: solo se ve el cálculo. Cuando se pase a real y se active, se carga solo cada 15 minutos.', 'El pase nunca pisa un día ya controlado ni una fila que cargó el Dragonfish.'] },
    { icon: '🗒', titulo: 'Registro: quién hizo y quién autorizó', desc: 'En Ajustes → «Registro · quién hizo y quién autorizó» (solo admin) queda todo lo que pasa en el POS con la hora exacta: cada comprobante emitido (factura, nota de crédito, remito, presupuesto), cada anulación, cada movimiento de stock manual y cada pedido de autorización, también los rechazados o los que no se usaron.',
      pasos: ['Columna «Quién»: la persona que lo hizo y cómo lo supo el POS: «cámara» (la reconoció), «eligió su nombre» (a mano) o «su usuario» (entró con su usuario personal). Si fue con el usuario genérico del local, lo aclara.', 'Columna «Autorizó»: quién autorizó y por qué camino: cámara, celular o usuario y clave.', 'Se filtra por fechas y por local, y el buscador encuentra por persona, número de comprobante o artículo. El ojo abre el comprobante.', 'Sirve para cruzar con las cámaras del local: la hora está con segundos.'] },
    { icon: '🗣', titulo: 'Pedirle a Clodi que arme una venta', desc: 'A Clodi se le puede pedir que deje cargado un ticket: por ejemplo «haceme una factura con el código SMINI por 1, en efectivo» o «armame un presupuesto con RECTOGR3 por 4 y SRECTO por 2». Clodi busca los códigos, carga los artículos con sus cantidades en Vender y, si le dijiste la forma de pago, la deja puesta por el total.',
      pasos: ['Clodi solo PREPARA: te muestra el resumen con el total y el ticket queda cargado en pantalla para revisar.', 'Si tocás «Enviar» en el cartel de Clodi es lo mismo que tocar Emitir: el POS sigue con lo de siempre (cliente, quién emite, autorización si hace falta). Si tocás «Cancelar», el ticket queda cargado para que lo sigas a mano.', 'Los artículos se piden por código. Si un código no existe en el local, Clodi avisa cuál y no carga nada. Si falta stock, lo avisa en el resumen.', 'Formas de pago que entiende: efectivo, dólares, Point, QR, link de pago, transferencia y vale. El cliente y los descuentos se cargan a mano.'] },
    { icon: '🔐', titulo: 'Autorizaciones: cámara, celular o clave', desc: 'Lo que necesita autorización (nota de crédito, remito, movimiento de stock, anular, pedidos, mínimos, emitir sin verificar un cobro, registrar una cara) se autoriza por tres caminos, en este orden. En todos queda anotado quién autorizó y cómo.',
      pasos: ['1) Cámara: se abre sola. Si quien está frente a la caja es la encargada o la cajera del local (o un admin) y tiene la cara registrada, queda autorizado al instante con su nombre, sin mandar nada al celu. Para los movimientos de stock tiene que ser la encargada o un admin.', 'Si la cámara reconoce a una vendedora, avisa que eso lo autoriza la encargada o la cajera y pasa al camino 2. Si no reconoce a nadie en unos 9 segundos, también. Con «Pedir al celu o con clave» se saltea la cámara.', '2) Pedir al celu: la ventana muestra primero quiénes están en el local ahora (según el reloj y los turnos) y después quiénes no están. Se le puede pedir a cualquiera: la encargada puede autorizar desde donde esté. Le llega la notificación para aceptar o rechazar.', '3) Usuario y clave: en la misma ventana, abajo, quien autoriza escribe su usuario y su clave.', 'La cara se registra una vez en Ajustes → «Quién emite · reconocimiento por cámara». Si la computadora no tiene cámara o nadie con rango registró su cara, la ventana arranca directo en el camino 2.', 'La comparación de la cara se hace en el servidor: las huellas no se bajan a la computadora del local.'] },
    { icon: '📷', titulo: 'Quién emite · reconocimiento por cámara', desc: 'En el local queda abierto el usuario genérico, así que el POS necesita saber qué persona emite cada comprobante. Al tocar Emitir (factura, nota de crédito, remito, presupuesto) se abre la ventana «¿Quién emite?»: mira por la cámara, reconoce a quien está en la caja y sigue solo. El nombre queda en el comprobante como quien emitió.',
      pasos: ['Registrar la cara: Ajustes → «Quién emite · reconocimiento por cámara» → «Registrar cara» al lado del nombre. La lista muestra primero a las personas del local en el que está abierto el POS y después a las de los otros locales, con el nombre del local al lado, así un admin puede registrar la cara de cualquiera desde cualquier PC que tenga cámara. Es una pasada guiada de tres tomas seguidas: de frente, girando un poco la cabeza a la izquierda y girando un poco a la derecha (medio perfil, que se sigan viendo los dos ojos). La pantalla va diciendo cuál toca; en cada una se toca «Capturar» y dos segundos sin moverse. Al terminar pide una sola autorización de la encargada o la cajera y guarda las tres. Quien usa lentes toca después «+ Uso lentes» y repite las mismas tres tomas con los lentes puestos: así el POS la reconoce con o sin lentes y de frente o de costado, sin tener que sacárselos. «Volver a registrar» reemplaza las tomas; el tacho las borra todas.', 'Al emitir: mirar a la cámara; cuando aparece el tilde verde con el nombre, sigue solo. Es obligatorio: sin saber quién emite no sale el comprobante.', 'Si no reconoce, la computadora no tiene cámara o todavía nadie registró su cara: en la misma ventana se elige el nombre a mano entre las empleadas del local. Los admin aparecen siempre en esa lista, en cualquier local, porque pueden emitir desde cualquiera. Si la cámara no abre, la ventana dice por qué (sin permiso del navegador, no hay cámara, o la está usando otro programa).', 'Si quien entró al POS lo hizo con su usuario personal de empleada (no el genérico), no abre la cámara: ya sabe quién es y avisa «Emite …» con su nombre. Con el usuario genérico del local o con un usuario admin siempre pasa por la cámara.', 'No se guarda ninguna foto ni video: solo una huella numérica de la cara, que se puede borrar o volver a registrar desde Ajustes (con autorización).', 'La primera vez que se usa en cada computadora tarda unos segundos más porque baja el reconocimiento; el navegador pide permiso para usar la cámara y hay que aceptarlo.'] },
    { icon: '💬', titulo: 'Botones de WhatsApp', desc: 'Los botones de WhatsApp del POS (mandar un vale o una gift card, el pedido al proveedor) se abren donde esa computadora tiene la sesión de WhatsApp del local.',
      pasos: ['En las PC de los locales el chat se abre en la ventana de WhatsApp del kiosco (la misma que usa el módulo Clientes), con el mensaje ya escrito: solo queda apretar enviar.', 'La primera vez el navegador pregunta si permite abrir el programa: tildá «Permitir siempre» y aceptá.', 'Si un botón de WhatsApp abre una página que pregunta «app o WhatsApp Web» o pide escanear un QR, esa computadora no está configurada: avisale a JP.', 'Se configura una sola vez por computadora (solo admin): Ajustes → «WhatsApp en esta computadora» → «Ventana de WhatsApp del kiosco». También sirve abrir el POS una vez con ?wa=kiosco al final de la dirección. En los celulares no se toca nada: abre la app de WhatsApp como siempre.'] },
    { icon: '🧪', titulo: 'Ambiente de prueba', desc: 'Mientras arriba de todo aparece la franja roja «AMBIENTE DE PRUEBA», el POS está en modo prueba para todos los locales: se puede practicar todo (facturas, notas de crédito, presupuestos, remitos, señas, gift cards, vales, pedidos, etiquetas) sin que nada sea real.',
      pasos: ['Las facturas y notas de crédito de prueba NO van a ARCA: no tienen CAE ni valor fiscal. Salen con numeración propia (punto de venta 9999) y con la leyenda «PRUEBA · SIN VALOR FISCAL» en el ticket, en la hoja A4 y en el PDF. En Comprobantes figuran con la etiqueta roja «Prueba».', 'El stock no se mueve: una venta de prueba no descuenta mercadería (el movimiento queda anotado en el historial del artículo, marcado como prueba, solo para ver cómo funciona).', 'La caja de prueba es aparte: en Caja se ve solo lo cobrado en prueba.', 'Mails: ningún mail de prueba le llega al cliente ni al proveedor. Todos van a la casilla de prueba (la de JP), con «[PRUEBA]» en el asunto.', 'Gift cards, vales de cambio y señas de prueba se generan y se usan solo dentro de la prueba: un vale de prueba no sirve en una venta real y uno real no se puede gastar en prueba.', 'Pedidos: el pedido a Familia García NO sale al proveedor; el mail va a la casilla de prueba y el botón de WhatsApp abre el número de prueba. El pedido a Oficina y los remitos de traslado funcionan entre los locales, pero el módulo Stock no los ve.', 'OJO con el Point: Mercado Pago cobra de verdad aunque el comprobante sea de prueba. Usalo solo si JP pidió probarlo (cobro y devolución).', 'Las autorizaciones al celular llegan con «PRUEBA» en el título.', 'Solo el admin, desde Ajustes → Ambiente de prueba, pasa el POS a REAL (hay que escribir REAL para confirmar), vuelve a prueba, cambia el mail y el WhatsApp de prueba, y borra todo lo de prueba cuando ya no hace falta. Al pasar a real lo de prueba deja de verse.'] },
    { icon: '🔐', titulo: 'Entrar y elegir el local', desc: 'Las dos cuentas de la oficina (administracion@claudiaadorno.com y claudiaadorno@claudiaadorno.com) entran directo en Oficina y ahí usan todo el POS: vender, comprobantes, remitos, caja, pedidos que le hacen los locales, etiquetas y vales. En el selector de local también les aparecen Alcorta y Unicenter con la marca «solo ver»: ahí pueden mirar los comprobantes, la caja y los pedidos de ese local, pero no pueden vender, emitir ni cambiar nada en nombre del local. Para operar tienen que volver a Oficina. Ajustes sigue siendo solo de los admin. Entrás con tu usuario de Colaboradores. Arriba, al lado del título, se elige desde qué local se factura: las vendedoras y encargadas pueden usar su propio local u Oficina (para lo que se factura desde allá), nunca el otro local; el admin elige cualquiera.',
      pasos: ['Lo que emitís sale con el punto de venta y la numeración del local elegido, y aparece en los Comprobantes y la Caja de ese local.', 'Si dice que no tenés acceso, tu legajo no tiene local asignado: avisale a JP.', 'Código del celular (doble factor): si sos admin o directora y lo activaste en el Hub (panel de sesión, "Código del celular al entrar"), en cada computadora te pide, después de la clave, el código de 6 números de la app de autenticación del celular (Google o Microsoft Authenticator), y después una vez cada 30 días. En el celular registrado con "Entrar con la cara en este equipo" no hace falta ni clave ni código: te pide la cara (o la huella) al abrir. Si cambiás o perdés el celular, avisale a JP para darlo de baja.', 'En el celular o la tablet se instala como app: Safari "Compartir → Agregar a pantalla de inicio"; Chrome "Instalar".'] },
    { icon: '🛒', titulo: 'Vender', desc: 'Los renglones del ticket van en colores alternos (blanco y celeste clarito) para leerlos más fácil. En la computadora cada renglón muestra la foto grande, el código, la descripción y debajo la descripción adicional, con cantidad, precio, descuento e importe en letra más grande. En el celular o en una ventana angosta el renglón va compacto: solo código y descripción, sin la descripción adicional. A la izquierda buscás los productos; a la derecha se arma el ticket. Cantidad primero: escribís 12 y + (o 12+) y Enter, queda el chip 12 ×, y el próximo producto que escanees, escribas o toques entra con 12 unidades; también todo junto, 12 SMINI. Sirve en factura, nota de crédito, presupuesto, remito y artículos señados. Cambios: si el cliente trae un artículo, se escribe la cantidad en negativo en la factura (por ejemplo -1): se descuenta del total y ese artículo entra al stock; el renglón queda violeta con el chip cambio · entra. En la nota de crédito es al revés: el negativo sale del stock. El total nunca puede quedar negativo. La vista previa de la hoja A4 se escala sola para que entre entera en la pantalla. Doble clic sobre un producto de la lista o sobre la ficha (o el link Ficha completa) abre en una subventana la ficha completa del módulo Productos, con todo lo que tiene cargado; se puede abrir en pestaña aparte. Doble clic sobre la ficha del producto, o sobre un renglón del ticket, abre en una subventana la ficha completa del módulo Productos (ahí están el historial de movimientos de stock y el resto de los datos). La ficha de la izquierda no tiene enlaces: muestra la foto con el stock de cada local debajo, y a la derecha el código, la descripción y la descripción adicional siempre completos (si son largos la letra se achica para que entren), el material y el nombre del proveedor (sin título, separados por un punto), y el precio con el botón + abajo. Para sacar el cliente del ticket está la cruz roja gruesa, a la derecha de sus datos; la misma cruz roja saca un renglón del ticket. El CUIT o CUIL del cliente se puede escribir o pegar con guiones, puntos o espacios (30-70967311-0): el sistema se queda con los números, tanto en el buscador de clientes como en la ficha de alta. Hasta el cierre del año el stock que se muestra viene del Dragonfish y el libro ya anota cada movimiento; después manda el libro: la factura o el comprobante X bajan el stock, la nota de crédito lo sube, la anulación lo deshace, la seña no lo toca (es una reserva) y la gift card no es un artículo. Al cargar un cliente que tiene remitos sin facturar, el POS avisa y ofrece Facturar este remito: entran los artículos marcados entregado y esa factura no vuelve a descontar stock. En el banner de arriba, A− y A+ agrandan o achican la letra, los números, las casillas y las fotos de todas las pestañas (Vender, Comprobantes, Caja, Vales, Configuración), de 90 a 150 %; el banner no cambia. En Vender se arrastra la barrita gris del medio para repartir el ancho entre productos y ticket. La flechita ↺ del banner vuelve a lo normal (letra 100 % y reparto de siempre). Queda guardado en esa computadora o tablet (cada una tiene el suyo). En el celular no hay A−/A+ y las ventanas van una debajo de la otra. Es la pantalla del mostrador.',
      pasos: ['Escribí parte del código o de la descripción: arriba a la izquierda aparece la ficha del primer resultado (foto grande, descripción, material, proveedor, stock en cada local y precio), siempre del mismo tamaño para que no salte al pasar de un artículo a otro y abajo la lista. Pasando el mouse por otro de la lista la ficha cambia; tocándolo, o con el botón Agregar de la ficha, entra al ticket. En el ticket cada renglón muestra una miniatura de la foto. Al agregar un artículo o subir la cantidad suena un bip que sube; al sacarlo o bajar la cantidad, uno que baja (hay que tener el volumen de la compu prendido).', 'Con el lector de etiquetas: escaneá el QR con el cursor en el buscador y el artículo entra solo (el QR trae el SKU).', 'En cada renglón podés cambiar la cantidad (+ / −), el precio y el descuento (casilla Dto): un número solo son pesos que se descuentan al precio unitario (1000 = $1.000 por unidad); con % al final es porcentaje (10%). Abajo hay un descuento general con la misma regla que el Dto del renglón: un número solo son pesos (5000 = $5.000), con % al final es porcentaje (10%). Con el "+" del renglón se agrega otro descuento; se aplican en cascada, cada uno sobre lo que queda. Con descuento en pesos el total cierra exacto.', 'Arriba elegís qué sale con las pastillas Factura, Nota de crédito y Presupuesto. Al tocar Presupuesto, abajo junto a la observación aparece un tilde "Presupuesto": sin tildar es un comprobante manual (interno, no va a ARCA), tildado es un presupuesto de verdad. La letra no se elige: Factura sale B (consumidor final, monotributista, IVA exento, no responsable o no alcanzado; todos menos consumidor final llevan CUIT), Factura A (responsable inscripto, pide CUIT), Factura manual (comprobante interno X que no va a ARCA), las notas de crédito B y A (devoluciones) y Presupuesto (no es venta: no va a ARCA ni a la caja, y después se factura desde Comprobantes con el botón de cobrar).', 'Al cargar un cliente con CUIT la pastilla pasa sola a "Factura A" (si el cliente no tiene condición de IVA cargada, con CUIT se lo toma como responsable inscripto; si es monotributista o exento, corregilo en la ficha o dejá que el padrón de ARCA lo complete, y vuelve a B) y abajo del subtotal aparecen el neto gravado y el IVA 21%, como en el comprobante; si lo sacás, vuelve a B. La nota de crédito toma la letra de la factura que devuelve. El documento cambia de fondo según el tipo: naranja claro cuando es nota de crédito, rojo clarito cuando es manual y celeste cuando es presupuesto, para notarlo de un vistazo. Mercado Pago Point integrado: primero, en Ajustes, "Mi Point en esta caja": cada computadora o tablet elige su terminal y queda guardado ahí. En el ticket, con forma de pago Mercado Pago Point (Integrado) aparece el botón "Cobrar $ en el Point": manda el importe a la terminal, se abre la ventana "Esperando el pago" y el cliente elige cuotas y pasa la tarjeta en el Point (mínimo $ 15; vence a los 3 minutos). Si la terminal no lo muestra, tocá el botón verde del Point. Cuando Mercado Pago aprueba, el renglón queda "pagado" en verde con el número de operación y recién ahí se puede emitir la factura. Rechazado, cancelado o vencido: no se emite nada, se reintenta o se cambia el medio. "Cancelar el cobro" lo cancela desde el POS; también se puede cancelar en la terminal. Si el Point tiene un cobro sin terminar, hay que finalizarlo o cancelarlo en la terminal antes de mandar otro. Devoluciones: una nota de crédito sobre una venta cobrada con Point integrado, con forma de devolución Mercado Pago Point, devuelve la plata a la misma tarjeta por Mercado Pago al emitir (hasta 90 días); si Mercado Pago no lo permite, el POS avisa y se hace desde la terminal. "No integrado" sigue siendo cobrar a mano en el Point y anotar el cupón. Gift card digital: escribí "gift" en el buscador y tocá la pastilla. Entra un renglón "Gift card" con el importe libre (sin descuento) y abajo el cuadro: para quién, de parte de quién, mail o WhatsApp de quien la recibe, la dedicatoria y el tilde "Mostrar el importe en la tarjeta" (sin tildar, el regalo no dice el precio; quien la recibe ve su saldo con el link). En todas las casillas de plata (precio, importe de la gift card, pagos, dólares) el separador de miles aparece solo mientras se escribe (23000 se ve 23.000); los centavos van con coma. Para venderla: escribí «gift» en el buscador de productos; aparece la tarjeta negra con una casilla de importe. Escribí el importe (se ve en la tarjeta), Enter o «Agregar», y pasa al ticket con ese importe ya puesto; después se completa para quién es y a dónde se manda. Se cobra con cualquier medio y sale con FACTURA legal (B, o A si el cliente es responsable inscripto): la gift card se factura al venderla, con CAE, y entra en la caja del día como venta (decisión de JP, 9-nov-2026). La gift card va siempre con la pastilla Factura: si se cambia a Presupuesto o a Nota de crédito, la gift card se saca del ticket. Cuando la usan, esa plata ya está facturada: en la factura de la compra la gift card se descuenta del total (renglón «Gift card ya facturada», como la seña), se factura solo la mercadería y se paga la diferencia con cualquier medio; si la compra es menor que la gift card, la factura sale en cero y queda saldo para otra vez. El uso de la gift card no entra en la caja (la plata entró el día que se vendió). Las gift cards viejas que salieron como comprobante X (antes del 9-nov) siguen usándose como forma de pago común. El vale de cambio no cambia: nace de una nota de crédito, así que la compra nueva se factura entera y el vale es un medio de pago. En el ticket, el renglón de la gift card se reconoce por la tarjetita negra en chiquito. El vale de cambio se manda por mail y por WhatsApp a la vez: al devolver con vale hay dos casillas, mail y WhatsApp, que vienen cargadas con los datos del cliente. Al emitir aparece el código (GC-XXXX-XXXX-XXXX) con su QR: el mail lo manda el servicio solo, con la tarjeta y la dedicatoria, y en la misma ventana está la casilla del WhatsApp con el botón «Enviar por WhatsApp», que abre el chat con el mensaje y el link listos (si no se había cargado el número, se escribe ahí mismo; sirve igual para la gift card); sin contacto, se copia el link y se pasa a mano. La tarjeta se ve en una página web: frente con la dedicatoria, se toca y gira al dorso con el código y el QR, y abajo el saldo. No vence y se puede usar en varias compras hasta agotar el saldo. Vale de cambio: en una nota de crédito, en "Cómo se le devuelve la plata" elegí "Vale / Gift card": no se mueve plata, al emitir nace un vale (VC-XXXX-XXXX-XXXX) por ese importe a nombre del cliente de la factura, sin vencimiento, y se manda al mail o WhatsApp que figura en ese renglón (con la nota de crédito adjunta si va por mail). Cobrar con un vale o una gift card: medio de pago "Vale / Gift card" y el código tipeado o escaneado con el lector (si se escanea el QR con el cursor en el buscador, el POS lo manda solo al renglón de pago). El POS consulta el código al instante: verde con el saldo si está vigente (sugiere usar el saldo o lo que falta, lo que sea menor; el resto queda en el mismo código), rojo si no existe, está anulado o ya se usó entero (dice cuándo y en qué factura). No se puede emitir con un vale sin verificar, ni usar el mismo código dos veces en un ticket, ni pagar una gift card con otro vale. Nunca se devuelve en efectivo el resto de un vale. El canje se hace en la base en el mismo paso que la factura, así dos cajas no pueden usar el mismo código a la vez. Pestaña Vales (menú de arriba): lista gift cards y vales con para quién, de qué comprobante nacen, importe, saldo y si el mail salió; se puede buscar por código, nombre o mail. El ojo muestra en qué compras se usó, el sobre lo reenvía (a otro mail o WhatsApp si hace falta), el documento abre la tarjeta y la cruz lo anula con motivo (encargada o admin; un vale usado entero no se anula). Anular el comprobante que vendió una gift card anula la gift card si todavía está intacta. Seña: escribí "seña" en el buscador y tocá la pastilla azul. Entra un renglón "Seña a cuenta" donde ponés la plata que deja el cliente, y abajo la subtabla "Artículos señados": buscá y tocá los productos que reserva (con su cantidad). Hace falta cliente con DNI o CUIT. Sale como factura por el importe de la seña; los artículos quedan reservados (se restan del stock que se ve) y no vence. Cuando el cliente vuelve y lo cargás, el POS avisa que tiene una seña y con "Usar esta seña" entran los artículos reservados al precio que tenían el día de la seña (si hubo aumento, lo señado no aumenta) y se descuenta lo ya pagado: la factura sale por el total menos la seña y paga el saldo. El total tiene que ser igual o mayor que la seña. Si no retira, la seña se cancela con una nota de crédito de su factura. Nota de crédito: elegís la pastilla y abajo aparece un cuadro naranja para buscar la factura que devuelve (número como 35-2, DNI o nombre del cliente). Al tocarla entran sus artículos al ticket: sacá o bajá la cantidad de lo que no vuelve. El cliente es el mismo de la factura y no se cambia. Abajo elegís cómo se le devuelve la plata.', 'El ticket arranca sin cliente: en el cuadro Cliente se carga el DNI o CUIT (tipeado o escaneando el DNI con el lector). Si existe lo trae; si no, abre la ficha para darlo de alta. Con consumidor final la factura B va a ARCA sin datos del cliente (él queda en nuestra base); si el cliente pide la factura con sus datos, tildá "a su nombre" (arriba del tope de ARCA va identificada sí o sí). Abajo del cliente hay una casilla aparte con su mail, que es por donde se manda la factura: es opcional; si se escribe ahí mismo, Enter o salir de la casilla lo guarda en la ficha. Alta rápida de cliente: si escribís un DNI que no existe, no se abre la ficha; queda el DNI en el ticket y abajo aparecen dos casillas, «Nombre y apellido» y «Mail». Escribís el nombre completo de corrido (Juan Pablo Simonelli) y el sistema lo separa solo en nombre y apellido (la última palabra es el apellido; si el apellido es compuesto, escribilo con coma: Pérez García, Ana); Enter lo da de alta y pasa al mail, que es opcional. Si el DNI se escanea, el nombre sale del DNI y el cliente queda dado de alta sin escribir nada. El lector funciona aunque la compu tenga el teclado en español (ahí escribe comillas en vez de arrobas). Para completar más datos (celular, dirección, cumpleaños) tocá el cliente y se abre la ficha. No se puede emitir con un cliente nuevo sin nombre: se carga o se saca con la X. Ver la sección Clientes.', 'Un renglón con borde ámbar es un artículo sin stock en este local: se vende igual, pero avisá. Cambiar de pastilla (Factura, Nota de crédito, Presupuesto) no borra los artículos cargados. Al lado de las pastillas hay tres botones: el tacho limpia todo el documento, el ojo muestra una vista previa (sin emitir, sin número ni CAE) con dos pestañas, Comandera y Hoja A4, y la impresora de al lado manda la comandera a imprimir; desde la pestaña Hoja A4 de la vista previa se imprime la A4.'] },
    { icon: '👤', titulo: 'Clientes', desc: 'Mientras escribís en la casilla del cliente (nombre, DNI o CUIT, 3 letras o números) se abre un desplegable con las 5 coincidencias más cercanas, con documento y última compra: tocás una o Enter toma la primera. En el buscador de productos pasa lo mismo: muestra las 5 más cercanas y avisa cuántas más hay. Todas las ventas llevan cliente: así queda en nuestra base para mandarle la factura, saludarlo en el cumpleaños y saber qué compra. Se identifica por DNI o CUIT, nunca por un código.',
      pasos: ['En el cuadro Cliente del ticket escribí el DNI (7 u 8 dígitos) o el CUIT (11) y Enter, o pasá el DNI por el lector de códigos (lee el código de atrás del DNI, también el DNI viejo): trae apellido, nombre, fecha de nacimiento y sexo solos. Si el cursor estaba en el buscador de artículos, también lo detecta.', 'Si el cliente ya está en la base, aparece en el ticket. Si es un CUIT que no existe se abre la ficha (trae los datos de ARCA): con * es obligatorio (documento y apellido o razón social); mail, celular, dirección, fecha de nacimiento y condición de IVA se pueden completar otro día. El celular se guarda en formato WhatsApp.', 'Con CUIT el POS consulta solo el padrón de ARCA y trae razón social, condición de IVA y domicilio. Responsable inscripto → factura A; monotributista, exento, no responsable o no alcanzado → factura B con CUIT.', 'Tocando el cliente en el ticket (o el lápiz) se abre la ficha para corregirla. A la izquierda muestra desde cuándo es cliente, cuántas compras lleva y qué se llevó la última vez (con foto): sirve para charlar con el cliente, por ejemplo preguntarle cómo le resultó lo que compró. La cruz lo saca del ticket. La lupa busca por nombre si no tenés el documento.', 'Abajo del tope de ARCA la factura B sale a "Consumidor Final" sin datos aunque el cliente esté cargado: a ARCA no va nada y el cliente queda vinculado en nuestra base (en Comprobantes se ve con 👤). Desde el tope (hoy $10.000.000, el sistema lo relee en ARCA todos los meses) la factura va identificada sí o sí.', 'Si cobrás sin cliente, el POS pregunta: "Cargar cliente" o "Seguir como Consumidor Final". Queda registrado qué ventas salieron sin cliente.', 'Lo que se carga o corrige también se manda al Dragonfish hasta fin de diciembre, para que los dos sistemas tengan lo mismo.'] },
    { icon: '💳', titulo: 'Cobrar', desc: 'En el comprobante X (el rojo, Presupuesto sin tildar) la única forma de pago es efectivo, en pesos o en dólares; el renglón viene ya en Efectivo. Efectivo dólares: elegís ese medio, escribís los dólares y el sistema calcula los pesos con el tipo de cambio del día (promedio entre compra y venta del dólar billete del Banco Nación, se actualiza solo cada hora; se puede corregir en el renglón). El ticket y el A4 muestran US$ × tipo de cambio y el importe en pesos; en Caja aparece Dólares en caja. El admin puede fijar el tipo de cambio a mano por el día en Ajustes. La forma de pago está a la vista en el ticket, abajo de los totales. Se pueden combinar varios medios (por ejemplo parte en efectivo y parte con Point).',
      pasos: ['El renglón arranca sin medio elegido (así la factura no se emite sin querer): hay que elegirlo en el desplegable (cada uno con su ícono: billetes para efectivo, tarjeta, celular para Point, etc.; al elegirlo el ícono hace un saltito) y el importe. Mercado Pago Point y QR aparecen una sola vez: abajo del renglón sale una pastilla partida Integrado | No integrado, con Integrado por defecto; si el cobro se hizo fuera de la integración, tocá "No integrado". Con un solo renglón el importe se sugiere solo con el total. Para pagos combinados (parte efectivo, parte tarjeta) tocá el "+" al final del primer renglón: el renglón nuevo trae lo que falta.', 'Tarjeta, link, transferencia y vale piden una referencia (número de cupón, etc.).', 'Si en efectivo cargás más que el total, abajo aparece el Vuelto y la venta queda registrada por el total.', 'El botón de abajo dice qué va a emitir (factura B, A, manual o NC) y se habilita cuando lo pagado cubre el total. Al emitir aparece el comprobante: la factura y la nota de crédito electrónicas se imprimen en la comandera desde el ícono de la impresora (logo, local, detalle, QR y CAE de ARCA, datos fiscales y contacto al pie; en Atelier Libertador sale el logo con la firma Atelier). La factura manual y el presupuesto no se imprimen: quedan en pantalla y en Comprobantes. Además, de cada comprobante emitido se arma solo un PDF en hoja A4 (el que va por mail al cliente, con la foto de cada artículo): aparece el botón PDF en el comprobante y en la lista de Comprobantes apenas está listo (las facturas electrónicas, en cuanto tienen CAE). Los medios de pago son los mismos códigos que el Dragonfish (efectivo, MP Point, QR, tarjeta…), así Ventas los suma igual.'] },
    { icon: '🔐', titulo: 'Autorizaciones', desc: 'Todos entran con el usuario genérico del local y ven todas las funciones. La nota de crédito, el comprobante X rojo, el remito y la anulación piden autorización de una persona de rango mayor: encargada, cajera (rango nuevo) o admin, siempre una persona con legajo, nunca el genérico. Al tocar Emitir aparece la ventanita con quiénes están en el local ahora (según el reloj de fichadas de hoy; si todavía no subió, el turno planificado en RRHH): tocás Pedir a esa persona y le llega un aviso al celu (app RRHH) con Aceptar y Rechazar; cuando acepta, el comprobante sale solo. Si no hay nadie, se le puede pedir a un admin. Si no tienen el celu a mano, en la misma ventanita cargan usuario y clave. La autorización vale 10 minutos, para ese solo comprobante, del mismo local; la traba está en la base. En Comprobantes queda quién autorizó y cómo (push o clave). Una encargada, cajera o admin logueada con su propio usuario emite sin pedir nada. El admin asigna los rangos en Ajustes.' },

    { icon: '🧾', titulo: 'Comprobantes', desc: 'Lista de lo emitido en el local por rango de fechas, con filtro por tipo y buscador por cliente, número o vendedora. Al abrir un comprobante se ve con las mismas pestañas que la vista previa: Comandera (ticket) y Hoja A4, más el PDF si ya está armado; el botón de imprimir imprime la pestaña que se está viendo.',
      pasos: ['El ojo abre el comprobante y permite imprimirlo de nuevo.', 'Usuarios con el POS acotado: un admin puede dejarle a una persona solo algunas pestañas del POS. Por ejemplo, el usuario del depósito ve solo Remitos, Pedidos y Etiquetas: no tiene Vender, Comprobantes, Vales ni Caja, y el sistema tampoco le deja emitir facturas ni notas de crédito, solo remitos. Si a alguien le falta una pestaña que necesita, lo cambia un admin.', 'Seña con descuento: en el cuadro «Artículos señados», cada artículo tiene una casilla de descuento ($ o %). Un número son pesos por unidad; con % al final es porcentaje. El precio del artículo queda congelado ya con ese descuento: cuando el cliente vuelve y se usa la seña, el artículo entra al ticket a ese precio.', 'Ver un pedido ya hecho: en Pedidos → «Pedidos hechos», el ojo (o tocar el número del pedido) abre el pedido completo: a quién se pidió, quién lo pidió, el estado, cada artículo con su foto y cantidad, lo que llegó, la nota, y los botones de PDF y Excel. Lo puede abrir cualquiera del local, también el usuario genérico; es solo para mirar, no pide autorización.', 'Movimientos de stock: entre los motivos fijos está «Retiro de mercadería personal», para la mercadería que se lleva una colaboradora y después se le descuenta del sueldo. Filtrando Movimientos por ese motivo se ve todo lo retirado.', 'Presupuesto (con el tilde «Presupuesto»): sale con la leyenda «Los precios de este presupuesto se mantienen por 14 días corridos», con la fecha hasta la que valen, en la comandera, en la hoja A4 y en el PDF que se manda por mail.', 'Tarjeta de regalo (la de la página web): no es la «Gift card» digital. Es un artículo común con el código TARJETA DE REGALO: en Vender se escribe «tarjeta» o «regalo» en el buscador, se agrega al ticket y se le pone el importe a mano cada vez (no tiene precio fijo). No genera código ni vale, no manda nada al cliente y no mueve stock. La «Gift card» digital (escribiendo «gift») sigue igual: esa sí genera el código y se manda por mail o WhatsApp.', 'Numeración cuando facturan varias a la vez: el número de la factura no se toma al abrirla sino en el momento de tocar Emitir, de a una por punto de venta. La que emite primero se lleva el número más bajo, aunque haya empezado a cargar después. No puede haber dos facturas con el mismo número ni quedan huecos: si una emisión falla, su número queda libre para la siguiente.', 'Factura «En espera»: ARCA autoriza los números en orden. Si ARCA rechaza una factura (por ejemplo por un CUIT mal cargado), las que se emitan después en ese punto de venta quedan con la etiqueta «En espera» (al pasar el mouse dice cuál es la factura que las frena). No hay que hacerles nada: apenas se corrige y se reintenta la rechazada, las que estaban en espera piden su CAE solas, en orden.', 'La flecha hacia atrás arma la nota de crédito de esa factura: te lleva a Vender con sus artículos cargados para sacar lo que no vuelve y elegir cómo se devuelve la plata. La NC lleva la misma letra que la factura; una devolución de una factura manual sale como NC manual.', 'Anular (solo encargada o admin) deja el comprobante tachado con el motivo; no se puede anular si ya tiene notas de crédito. Los comprobantes electrónicos (factura, nota de crédito o nota de débito A o B) no se anulan nunca una vez que están en ARCA o se están informando: no aparece el botón de anular y el sistema lo rechaza, porque lo del POS tiene que coincidir 100 % con lo que ARCA tiene; se corrigen con una nota de crédito. Solo se puede anular el electrónico que ARCA rechazó (queda en rojo «CAE rechazado», nunca llegó a ARCA) y los comprobantes que no van a ARCA: X, remitos y presupuestos.', 'Estados: "CAE…" = la factura ya salió y el sistema le está pidiendo el CAE a ARCA (tarda unos segundos; el ticket se actualiza solo y aparece el QR de ARCA); "CAE" = autorizada; "CAE rechazado" = ARCA no la aceptó: el motivo está al pasar el mouse y la flecha ↺ la vuelve a pedir (encargada o admin). "Manual" = factura manual.'] },
    { icon: '🚚', titulo: 'Remitos', desc: 'Remito de venta: la mercadería sale sin cobrar (entrega a domicilio, cliente que factura después). «+ Remito» abre el remito nuevo en una ventana encima de la lista (se cierra con la cruz, con Escape o tocando afuera, y no emite nada); usa el mismo buscador y ticket de Vender, en color ámbar: cliente obligatorio, dirección y nota de entrega opcionales, sin pagos ni CAE, numeración propia del local. Al emitir baja el stock, se imprime en A4 con el logo para que viaje con la mercadería y, si el cliente tiene mail, se le manda. La lista muestra los remitos del local: Sin facturar o Todos, con el estado (sin facturar, facturado con el número de la factura, anulado). Facturar (desde acá, desde Comprobantes o al cargar el cliente en Vender) arma la factura con los artículos ya entregados y no descuenta de nuevo. Anular un remito devuelve la mercadería al stock; si ya se facturó no se puede anular: hay que anular o devolver la factura. El remito tiene tres destinos, en este orden: «A otro local» (viene elegido, es lo más usado), «A un proveedor» y «A un cliente». A un proveedor: para devolver mercadería o mandar mercadería defectuosa; elegís Familia García o Espalma de la lista o escribís el nombre de otro proveedor, ponés el motivo en la nota y emitís: baja el stock del local, no cobra y el remito sale a nombre de «Proveedor: …»; ese remito no se factura. Mercadería en tránsito: en «+ Remito» elegís A otro local, el destino y una nota para el transporte; al emitir baja del stock de este local y queda en tránsito (la encargada del destino recibe un aviso al celu). La pastilla En tránsito muestra, con un contador, lo que viene a este local y lo que este local mandó, con su estado: en tránsito, recibido (por quién y cuándo) o recibido con diferencia. Recibir es tarea de la encargada: cuenta renglón por renglón lo que llegó (lo enviado al lado), puede dejar una observación y acepta; lo aceptado entra al stock en ese momento y lo que falta queda marcado en rojo para que el origen lo resuelva (lo manda en otro remito o lo da de baja con un movimiento manual). Un traslado ya recibido no se anula. Lo que otros locales le piden a este ya no está en Remitos: pasó a la pestaña Pedidos, pastilla «Me piden» (con contador). Ahí aparece lo que otros locales le pidieron a este (pendiente, revisando o apartado); se marcan los que van al mismo local y Armar el remito con los marcados abre el remito de traslado ya cargado (destino, artículos, cantidades y nota con los números de pedido); al emitirlo los pedidos quedan enviados y apuntan al remito. Si algo ya salió sin remito, el tilde cierra el pedido sin mover stock. En todo remito (a otro local, a un proveedor o a un cliente) es obligatorio completar la cantidad de bultos: sin ese dato no deja emitir; sale en el remito como «Bultos: N» junto con la observación y se ve en En tránsito. Cuando la encargada recibe mercadería en tránsito, cada artículo recibido queda como un movimiento de stock («Recibido de un traslado») y aparece en la lista de Movimientos, con el enlace al remito. Etiquetas: cada movimiento de entrada tiene el botón de la impresora, que lleva a Etiquetas con ese artículo y esa cantidad ya cargados; y cada remito (en Sin facturar, Todos y En tránsito) tiene el mismo botón, que carga todos los artículos del remito. Es optativo: se usa cuando hace falta etiquetar. Pastillas de Remitos: «En tránsito» (traslados que el destino todavía no aceptó, de ida o de vuelta), «Aceptados» (traslados que el destino ya aceptó y entraron al stock, con quién los recibió y si hubo diferencia), «Todos» (todos los remitos del local y los traslados que le llegan, también los rechazados y los anulados; los remitos a un cliente que todavía no se facturaron se reconocen ahí por la marca amarilla «Sin facturar» y tienen el botón para facturarlos) y «Movimientos». En el renglón de cada remito en tránsito están el ojo (abre el remito; desde ahí se imprime) y, según el caso, «Aceptar» y «Rechazar» para el local que recibe, o corregir y anular para el local que lo mandó. Recibir mercadería en tránsito: en En tránsito, tocando el renglón del remito se despliega abajo la mercadería que viene (foto, código y cantidad). El local que la recibe tiene tres botones: «Confirmar: llegó todo» (entra al stock en ese momento), «Llegó con diferencia» (se cuenta lo que llegó y lo que falta queda marcado) y «Rechazar». Rechazar pide siempre el motivo: la mercadería no entra, vuelve entera al stock del local que la mandó, a ese local le llega el aviso al celu con el motivo, y el remito queda como «Rechazado» con el motivo a la vista. Confirmar y rechazar los hace la encargada; desde el usuario genérico piden su autorización (cámara, celu o clave). Si llegó menos de lo que decía el remito («Llegó con diferencia»): lo que llegó entra al stock del local que recibe, y lo que NO llegó no desaparece: queda en tránsito de vuelta al local que lo mandó, al que le llega un aviso al celu. Ese remito le aparece al local de origen en «En tránsito», con la marca «falta resolver», y tiene dos botones: «Volvió al stock» (la mercadería estaba ahí: vuelve a su stock) y «Faltante» (no aparece: se da de baja). Los dos abren una ventana donde se elige uno de los motivos fijos de Movimientos (Inventario, Rotura, Faltante, Error de carga…) y se escribe la observación (obligatoria si es faltante), y piden la autorización de la encargada. En los dos casos queda el movimiento de stock anotado en Movimientos, con el motivo elegido, la observación y el remito y el tránsito a los que corresponde, así se puede filtrar por motivo: «Volvió al stock» deja una entrada; «Faltante» deja la entrada de lo que volvió del tránsito y la baja como faltante. Esos movimientos no se anulan ni corrigen a mano. Hasta que el origen lo resuelve, el remito sigue contando en el numerito de «En tránsito». Y al revés, si llegó DE MÁS (el remito decía 1 y llegaron 2): en «Llegó con diferencia» se anota lo que llegó de verdad; entra todo al stock del local que recibe, y al local que lo mandó le llega el aviso y le aparece el remito en «En tránsito» con el botón «Dar de baja el sobrante», que descuenta de su stock lo que salió sin anotar. Mientras el destino no la aceptó, el local que emitió el remito de traslado puede anularlo (la mercadería vuelve a su stock) o corregirlo: «Corregir» anula ese remito y abre uno nuevo con los mismos artículos, destino y bultos para cambiar lo que haga falta y emitirlo otra vez. Una vez que el destino la aceptó (o la rechazó) ya no se puede anular ni corregir. El remito se imprime solo en hoja A4 (no sale por la comandera: la vista previa abre directo en A4) y se titula «Remito X», con el destino, la cantidad de bultos y la leyenda «no válido como factura». En el remito hay una casilla opcional «Quién lo transporta»: al tocarla ofrece los dos de siempre (Familia García Regueira con su chofer Néstor Donzelli, y Richard Soto, el flete propio) y también se puede escribir otra cosa, por ejemplo un flete tercerizado. No es obligatoria. Sale en la hoja del remito y se ve en En tránsito. Números únicos: cada remito se identifica con el local adelante (por ejemplo ALC 0002-00000015 es de Alcorta y UNI 0002-00000015 es otro, de Unicenter), y cada mercadería en tránsito tiene además su propio número, que no se repite nunca (por ejemplo TR-000062). Los dos aparecen en En tránsito, en Aceptados y en la hoja del remito. En la lista de Movimientos, todo lo que salió o entró por un traslado («Salió por traslado» / «Entró por traslado») muestra a qué remito y a qué tránsito corresponde, con el trayecto; tocando el número se abre el remito, y el buscador encuentra por cualquiera de los dos números. El remito no lleva descuentos (no tiene columna de descuento ni descuento general) y la nota va en la casilla Observación de abajo: no hay una casilla aparte de nota para el transporte. Movimientos (misma pestaña): entradas, bajas y ajustes de stock hechos a mano; los hace la encargada o, desde el usuario genérico del local (o el de la cajera), con la autorización de la encargada: al guardar aparece el cartel de autorización, se le pide al celu (o autoriza ahí con su clave); cada movimiento pide su propia autorización, igual que cada remito (la autorización que sirve para varias cosas seguidas durante 15 minutos es solo la de pedidos y mínimos); la cajera no autoriza movimientos, solo la encargada o un admin; queda anotado quién autorizó: botón «+ Movimiento» (arriba, al lado de «+ Remito») → Entrada (unidades que entran), Baja (unidades que salen) o Ajuste a (el stock que tiene que quedar), el producto, la cantidad y el motivo, que se elige de una lista fija (Inventario, Rotura, Ingreso de mercadería, Muestra, Uso interno, Regalo o cortesía, Devolución a proveedor, Faltante, Error de carga, Otro) con un detalle opcional; con «Otro» el detalle es obligatorio. Si alguien se equivocó al cargar un movimiento, cada renglón tiene dos botones: anular (el círculo tachado) y corregir (el lápiz). Los dos piden siempre el motivo y la autorización de la encargada. Anular restablece el stock y deja el renglón en la lista, atenuado y con la marca «Anulado», quién lo autorizó y el motivo: nada se borra. Corregir anula ese movimiento y abre uno nuevo ya cargado con lo mismo, para cambiar lo que esté mal y guardarlo (el nuevo pide su propia autorización, como todo movimiento). Un movimiento anulado no se puede volver a anular ni corregir. En la lista de Movimientos, la fila de pastillas «Motivo» filtra por cada uno y trae toda la tirada de ese motivo con la cantidad de movimientos y las unidades netas: por ejemplo todo lo ajustado en un inventario. «Traslado» muestra lo recibido de otro local; los movimientos viejos con motivo escrito a mano aparecen en «Otro». Queda en el libro con quién y por qué, y se ve en el historial de la ficha. Hasta el cierre del año el stock en pantalla sigue siendo el del Dragonfish; después el movimiento lo cambia al instante.' },

    { icon: '📦', titulo: 'Pedidos', desc: 'IMPORTANTE: desde el 12 de noviembre los Pedidos son reales, aunque el resto del POS siga en ambiente de prueba (el cartel rojo de arriba lo avisa: «los PEDIDOS sí son reales»). Un pedido a Familia García Regueira le llega a Víctor por mail (PDF y Excel, con copia a Administración) y se abre el WhatsApp con el texto listo. Un pedido a Oficina le llega al depósito: notificación al celular de Iván y de Rivera, mail con PDF y Excel, y WhatsApp a Rivera; en el depósito lo ven en su POS en Pedidos → «Me piden». Mientras los remitos se sigan haciendo en el Dragonfish, el local cierra el pedido tocando «Recibido» en «Pedidos hechos» cuando llega la mercadería. Los pedidos a Espalma todavía no tienen mail ni WhatsApp cargados. Un pedido enviado NO se modifica ni se cancela. Si hay que AGREGAR algo, se hace un pedido nuevo (queda como un agregado aparte). Si hay que SACAR algo que se pidió de más, en «Pedidos hechos» se toca «Descontar» en ese pedido: se pone cuánto sacar de cada artículo y se genera un descuento aparte, con número propio, que le llega al proveedor (o al depósito) por mail y WhatsApp con esas cantidades a descontar del pedido ya enviado; en la lista queda marcado «descuento de …» con las cantidades en negativo. No se puede descontar más de lo pedido. El descuento se cierra solo cuando se marca «Recibido» el pedido original. Cancelar un pedido entero solo lo puede hacer un admin. En «Qué falta», las columnas van: Otras sucursales, Stock, En tránsito, Ya pedido, Mínimo, Falta y Pedir. Pedidos del local (la pestaña no aparece cuando el POS está en Oficina: los pedidos de Oficina a proveedores van por el módulo Compras). Qué falta: para cada producto con mínimo muestra stock, en tránsito hacia el local, ya pedido, mínimo y falta (mínimo menos todo lo demás, nunca negativo), agrupado en Familia García Regueira (se le pide al proveedor) y Oficina (depósito, lo que Oficina ya compró, con cuánto tiene). Arriba, las pastillas Todos / Familia García / Espalma / Oficina filtran a quién se le pide (con la cantidad de artículos de cada uno): elegís Familia García, Marcar todos y armás ese pedido; después Espalma, y después Oficina. Hay tres destinos: Familia García Regueira y Espalma son proveedores a los que el local les pide directo (el pedido sale por mail en PDF con copia a Oficina y por WhatsApp; el mail y el WhatsApp de cada uno se cargan en Ajustes); todo lo demás se le pide al depósito de Oficina, y dentro de Oficina la lista viene ordenada y separada por proveedor. En «Qué falta» se elige a quién se le pide con las pastillas Familia García, Espalma u Oficina (viene elegida Familia García): se ve de a uno por vez, porque cada pedido va a un solo destino y nunca se mezclan. El mínimo se puede cambiar sin salir de «Qué falta»: la columna Mínimo es una casilla; se escribe el nuevo valor y, al salir de la casilla, se guarda (con la autorización de la encargada o la cajera) y se recalcula lo que falta de ese artículo, sin perder lo que ya estaba tildado ni las cantidades cambiadas. La pestaña Mínimos sigue estando para cargar o revisar todos juntos. Quién puede: en el local queda siempre abierto el usuario genérico. Armar, cancelar o recibir un pedido y cargar o cambiar un mínimo necesitan la autorización de la encargada, la cajera o el admin: al enviar el pedido (o al salir de la casilla del mínimo) aparece el cartel con quiénes están en el local, se elige a quién pedírselo y le llega la notificación al celu para aceptar o rechazar; si no tiene el celu a mano, autoriza ahí mismo con su usuario y clave. La autorización vale 15 minutos y sirve para varias cosas seguidas del mismo tipo (los pedidos de un armado, o varios mínimos), así no se pide una por una. Si quien está logueada ya es encargada, cajera o admin, no pide nada. En cada pedido y en cada mínimo queda anotado quién lo autorizó. Los artículos dados de baja (los que tienen el tilde «importado» en el Dragonfish, que es la marca de lo que ya no se trabaja) no aparecen en Qué falta ni en Mínimos, y tampoco se pueden agregar a mano a un pedido. Pedir algo que no está en la lista: en la barra de «Qué falta», el botón «Fuera de lista» abre una ventana para sumar al pedido del proveedor que se está viendo un artículo del sistema (por código o descripción) o un renglón libre para lo que no está en el sistema (resma de papel, cinta, lapiceras), cada uno con su cantidad. Lo sumado queda guardado (el botón muestra cuántos hay) y entra en el pedido al tocar «Armar pedido», junto con lo tildado, o solo si no se tildó nada. La ficha del pedido ya no tiene casillas para agregar: muestra los artículos con su cantidad, la nota para el proveedor y cómo sale. El pedido al proveedor (Familia García o Espalma) sale siempre en PDF y en Excel, los dos adjuntos en el mismo mail; en Pedidos hechos están los dos para abrir o bajar. La columna «Otras sucursales» muestra cuánto stock hay del mismo artículo en los demás locales (en verde) y en el depósito de Oficina (en gris), para ver si conviene pedírselo a otro local antes que al proveedor; si dice «no hay en otro lado» nadie tiene. Artículos con desglose (los que vienen juntos del proveedor, como el cesto de ropa recto grande y chico): aparecen juntos, con fondo naranja clarito y el cartel «Vienen juntos del proveedor», aunque a uno solo le falte stock y aunque el otro no tenga mínimo cargado; así no se deja de pedir el juego porque sobra de uno. El juego tiene una sola casilla de cantidad a la derecha, que vale para todos sus artículos (se pide esa cantidad de cada uno), y se marca o desmarca entero. Filtro Solo bajo mínimo; la columna Pedir viene con lo que falta y se puede cambiar; marcás y Armar pedido abre un pedido por destino. A Oficina: se crean los pedidos de traslado, Oficina los ve en su POS en Pedidos → Me piden, arma el remito con un clic y entran por En tránsito (aviso al celu de la encargada de Oficina). A Familia García: lista para controlar, nota, y al enviar sale el mail con el PDF (copia a Oficina, contactos en Ajustes) y se abre el WhatsApp con el texto del pedido; después se marca Recibido cuando llega (el stock entra con la compra o un movimiento manual). Mínimos: la encargada escribe el mínimo de cada producto para su local (cero lo saca); hasta el cierre del año los que no se tocaron vienen del Dragonfish y los cargados acá no se pisan. Pedidos hechos: cada pedido con estado (pendiente en Oficina, en tránsito con su remito, recibido, pendiente de entrega con mail y WhatsApp, cancelado).' },

    { icon: '🏷', titulo: 'Etiquetas', desc: 'Imprime la etiqueta de producto con el diseño C1 elegido el 30-oct: QR con el SKU a la izquierda (lo que leen los lectores de caja), el SKU grande, Claudia Adorno pegado debajo del SKU y la página www.claudiaadorno.com abajo, en el rollo de 3 bandas de 31,7 × 12,7 mm. La cantidad va primero: escribís 12 y + (o 12+) y Enter, y después escaneás o escribís el SKU: entra con 12; también todo junto, 12 SMINI. Sin cantidad entra de a una, y en la cola se corrige. A la derecha se ve en vivo cómo va saliendo el rollo, fila por fila; también desde la ficha del producto (Etiquetas ›) y desde En tránsito, el botón de imprimir en un traslado recibido carga lo que llegó. Con el POS en Oficina aparece el botón «Desde remito»: muestra los remitos de venta del Dragonfish de Oficina de los últimos 10 días (se actualizan solos cada medio minuto), con buscador por número o destino. Tocando uno, todos sus artículos entran a la lista de etiquetas con la cantidad del remito; se puede corregir o sacar alguno antes de imprimir. Es provisorio, mientras los remitos se sigan haciendo en el Dragonfish. Imprimir desde el celular en los locales: cada local imprime solo en su propia etiquetadora y solo estando en el local. El POS lo comprueba solo: si el celular está en el WiFi del local, imprime directo; si está con datos móviles, pide permiso para ver la ubicación y deja imprimir si está en el shopping. Desde afuera avisa que hay que estar en el local. Los admin imprimen desde cualquier lado. Las etiquetadoras se ven en Ajustes → «Etiquetadoras» (solo admin): estado, oscuridad, y el alta de la PC de cada local con el código de 6 números que muestra esa PC. La vista previa del rollo está siempre a la derecha y se actualiza sola. En «Rollo» está «Sentido»: «Girada 180°» (lo normal) o «Sin girar», por si en alguna impresora las etiquetas salen patas para arriba; la vista previa siempre se ve derecha. El botón «Imprimir» manda las etiquetas directo a la etiquetadora del local en el que está el POS, sin cuadro de impresión y sin elegir impresora: por eso se puede imprimir también desde el celular o la tablet. Debajo del botón dice por qué etiquetadora sale; si aparece «sin conexión», la PC que imprime está apagada y las etiquetas salen cuando vuelva. Al mandar, la lista se vacía sola y el POS avisa cuando quedaron impresas. Si un local tiene dos etiquetadoras (una común y una RFID), el POS separa solo: cada artículo va a la etiquetadora que le corresponde. «Desde esta PC» imprime por el cuadro de Windows eligiendo la impresora a mano, por si hace falta. Hoy está conectada la etiquetadora del depósito (con el POS en Oficina); en un local que todavía no la tiene conectada, «Imprimir» abre el cuadro de Windows como antes. El rollo (ancho, alto, cuántas por fila, separación, margen y nombre) se configura a la derecha y queda guardado en esa computadora; el de siempre es 31,7 × 12,7 mm, 3 por fila, 3,2 mm entre bandas y 2,5 mm de margen. Cualquiera puede etiquetar. Las etiquetas RFID nuevas (impresora Chainway) van por su propio circuito.' },

    { icon: '💰', titulo: 'Caja', desc: 'Lo cobrado en el día por medio de pago, con totales de facturado y de facturas manuales. Las notas de crédito restan y los anulados no cuentan.',
      pasos: ['Cambiá el día arriba para ver otro.', 'Sirve para el cierre: tiene que coincidir con lo que marca la planilla de Ventas.'] },
    { icon: '⚙', titulo: 'Ajustes (solo admin)', desc: 'Puntos de venta por local (fiscal y manual) y qué medios de pago se ofrecen.',
      pasos: ['Puntos de venta fiscales del POS en ARCA: 0033 Alcorta, 0034 Unicenter, 0035 Oficina; si se cambia el número la numeración sigue sola desde 1.', 'Un medio de pago apagado deja de aparecer al cobrar; "pide referencia" obliga a cargar el número de cupón.', 'Tope de ARCA para identificar al consumidor final: se muestra con la fecha de la última lectura; no se carga a mano, lo relee el servicio del CAE una vez por mes en la página de ARCA y avisa acá si no pudo.'] },
  ];
}

function abrirManual() {
  if (document.getElementById('manual-overlay')) return;
  const items = _manualSecciones();
  const ov = document.createElement('div');
  ov.id = 'manual-overlay';
  ov.innerHTML = `
    <div class="m-box">
      <div class="m-head">
        <span style="font-size:22px;">📖</span>
        <div style="flex:1;">
          <div style="font-weight:700;font-size:16px;">Manual · POS</div>
          <div style="font-size:12px;opacity:.85;">Guía rápida de cada herramienta del módulo</div>
        </div>
        <button class="m-close" onclick="cerrarManual()">✕</button>
      </div>
      ${items.map((s, i) => `
        <div class="m-sec">
          <div class="m-tit">${s.icon} ${i + 1}. ${_mEsc(s.titulo)}</div>
          <div class="m-desc">${_mEsc(s.desc)}</div>
          <ul class="m-pasos">${s.pasos.map(p => `<li>${_mEsc(p)}</li>`).join('')}</ul>
        </div>`).join('')}
      <div class="m-foot">💡 Este manual se actualiza junto con el sistema. ¿Falta algo o no funciona? Avisale a JP.</div>
    </div>`;
  document.body.appendChild(ov);
  _manualLupa(ov);
  document.body.style.overflow = 'hidden';
}

function cerrarManual() {
  const ov = document.getElementById('manual-overlay');
  if (ov) ov.remove();
  document.body.style.overflow = '';
}
document.addEventListener('keydown', e => { if (e.key === 'Escape') cerrarManual(); });

(function _manualInit() {
  const css = document.createElement('style');
  css.textContent = `
    #manual-overlay{position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:20px 12px;overflow-y:auto;-webkit-overflow-scrolling:touch;}
    #manual-overlay .m-box{background:#f8fafc;border-radius:14px;max-width:760px;width:100%;padding-bottom:6px;box-shadow:0 20px 60px rgba(0,0,0,.3);}
    #manual-overlay .m-head{position:sticky;top:0;background:#0e7490;color:#fff;padding:14px 18px;border-radius:14px 14px 0 0;display:flex;align-items:center;gap:10px;z-index:1;}
    #manual-overlay .m-close{background:rgba(255,255,255,.18);border:none;color:#fff;font-size:16px;border-radius:8px;padding:6px 11px;cursor:pointer;}
    #manual-overlay .m-sec{background:#fff;border:1px solid #e2e8f0;border-left:4px solid #0e7490;border-radius:10px;margin:14px 14px 0;padding:14px 18px;}
    #manual-overlay .m-tit{font-weight:700;font-size:15px;margin-bottom:4px;color:#155e75;}
    #manual-overlay .m-desc{font-size:13px;color:#475569;margin-bottom:8px;}
    #manual-overlay .m-pasos{margin:0 0 2px 18px;padding:0;font-size:13px;line-height:1.65;color:#334155;}
    #manual-overlay .m-pasos li{margin-bottom:4px;}
    #manual-overlay .m-foot{margin:16px 14px 12px;background:#cffafe;border-left:4px solid #0891b2;border-radius:8px;padding:11px 14px;font-size:12.5px;color:#155e75;}`;
  document.head.appendChild(css);

})();

// ── 🔍 Lupa del manual (29-sep, pedido Contreras): busca por palabra, sin tildes ni mayúsculas.
//    Deja solo las secciones que la contienen, dentro de ellas los pasos que la contienen,
//    y resalta la palabra. Mismo bloque en todos los módulos (el de RRHH usa _mLupaFiltrar).
function _mLupaNorm(s){ return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase(); }
function _mLupaMarcar(el, q){
  const nodos = [], w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  while (w.nextNode()) nodos.push(w.currentNode);
  nodos.forEach(n => {
    const t = n.nodeValue; let norm = '', mapa = [];
    for (let i = 0; i < t.length; i++){ const c = _mLupaNorm(t[i]); for (let k = 0; k < c.length; k++){ norm += c[k]; mapa.push(i); } }
    let desde = 0, pos, frag = null, ult = 0;
    while (q && (pos = norm.indexOf(q, desde)) >= 0){
      frag = frag || document.createDocumentFragment();
      const a = mapa[pos], b = mapa[pos + q.length - 1] + 1;
      if (a > ult) frag.appendChild(document.createTextNode(t.slice(ult, a)));
      const m = document.createElement('mark'); m.textContent = t.slice(a, b);
      m.style.cssText = 'background:#fde047;color:inherit;padding:0 1px;border-radius:3px'; frag.appendChild(m);
      ult = b; desde = pos + q.length;
    }
    if (frag){ if (ult < t.length) frag.appendChild(document.createTextNode(t.slice(ult))); n.parentNode.replaceChild(frag, n); }
  });
}
function _mLupaFiltrar(cont, selSec, texto, info){
  if (!cont) return;
  const q = _mLupaNorm(String(texto || '').trim());
  let vistas = 0;
  cont.querySelectorAll(selSec).forEach(sec => {
    if (sec.dataset.mOrig == null) sec.dataset.mOrig = sec.innerHTML; else sec.innerHTML = sec.dataset.mOrig;
    if (!q){ sec.style.display = ''; return; }
    const lis = [...sec.querySelectorAll('li')];
    const enLis = lis.filter(li => _mLupaNorm(li.textContent).includes(q));
    const hay = _mLupaNorm(sec.textContent).includes(q);
    sec.style.display = hay ? '' : 'none';
    if (!hay) return;
    vistas++;
    if (enLis.length) lis.forEach(li => { if (!enLis.includes(li)) li.style.display = 'none'; });
    _mLupaMarcar(sec, q);
  });
  if (info) info.textContent = !q ? '' : vistas ? `${vistas} ${vistas === 1 ? 'sección' : 'secciones'} con «${String(texto).trim()}»` : `No encontré «${String(texto).trim()}» en el manual.`;
  const primera = q && cont.querySelector('mark');
  if (primera) primera.scrollIntoView({block: 'center', behavior: 'smooth'});
}
function _manualLupa(ov){
  const head = ov && ov.querySelector('.m-head'); if (!head) return;
  head.style.flexWrap = 'wrap';
  const box = document.createElement('div');
  box.style.cssText = 'flex-basis:100%;display:flex;gap:8px;align-items:center;margin-top:8px';
  box.innerHTML = '<input type="search" placeholder="🔍 Buscar en el manual (por ej.: equivalencias, remito, echeq)…" '
    + 'style="flex:1;min-width:0;padding:8px 11px;border-radius:9px;border:none;font-size:14px;color:#0f172a;font-family:inherit">'
    + '<span class="m-lupa-info" style="font-size:12px;opacity:.9;white-space:nowrap"></span>';
  head.appendChild(box);
  const inp = box.querySelector('input'), info = box.querySelector('.m-lupa-info');
  let t = null;
  inp.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => _mLupaFiltrar(ov, '.m-sec', inp.value, info), 250); });
  inp.addEventListener('keydown', e => { if (e.key === 'Escape' && inp.value){ e.stopPropagation(); inp.value = ''; _mLupaFiltrar(ov, '.m-sec', '', info); } });
  setTimeout(() => inp.focus(), 50);
}
